with documented(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_basis,scope_note,source_version) as (values
(446,'market_launch','Honda CB650R — 2019 Neo Sports Café European introduction','{"style":"Neo Sports Café","equipment":"Radial-mount four-piston front brake calipers, selectable torque control and assist/slipper clutch","model_year":"2019","front_suspension":"41 mm Showa Separate Function upside-down fork","announcement_date":"6 November 2018"}'::jsonb,2019,NULL,'Europe','Honda Global — 2019 middleweight line-up, 6 November 2018','https://global.honda/en/newsroom/news/2018/2181106eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','2019 European CB650R first model introduction, not the fully faired CBR650R.','Honda Global — 2019 middleweight line-up, 6 November 2018'),
(502,'model_year','Kawasaki Versys 650 — updated 2022 model announcement','{"equipment":"Kawasaki Traction Control, LED headlights, adjustable windshield and connected 4.3-inch TFT screen","model_year":"2022","engine_type":"Parallel twin","announcement_date":"24 November 2021","engine_capacity_cc":649}'::jsonb,2022,NULL,'EICMA international model announcement','Kawasaki Heavy Industries — 2022 Versys 650 announcement, 24 November 2021','https://global.kawasaki.com/en/corp/newsroom/news/detail/?f=20211124_0706','manufacturer_primary_source_exact_model_checked_2026_11_12','2022 revised Versys 650 equipment, not previous-generation Versys 650 or Versys 1000.','Kawasaki Heavy Industries — 2022 Versys 650 announcement, 24 November 2021'),
(444,'engineering','Honda CB500F — 2019 European middleweight updates','{"equipment":"Assist/slipper clutch, full LED lighting, updated LCD instruments and revised rear suspension","model_year":"2019","engine_changes":"More mid-range power and torque between 3,000 and 7,000 rpm"}'::jsonb,2019,NULL,'Europe','Honda Global — 2019 middleweight line-up, 6 November 2018','https://global.honda/en/newsroom/news/2018/2181106eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','2019-specification revised CB500F, not 2013 first generation.','Honda Global — 2019 middleweight line-up, 6 November 2018'),
(445,'market_launch','Honda CB500X — original European model announcement at EICMA 2012','{"power":"35 kW","character":"On-off crossover with longer suspension travel than CB500F/CBR500R","engine_type":"New liquid-cooled parallel twin","announcement_date":"13 November 2012","european_model_year":"2013"}'::jsonb,2013,NULL,'Europe','Honda Global — 2013 line-up announcement, 13 November 2012','https://global.honda/en/newsroom/news/2012/2121113eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','Original CB500X announcement, not its 2019 updated geometry.','Honda Global — 2013 line-up announcement, 13 November 2012'),
(963,'specification','Suzuki GSX-S750 — 2017 factory archive technical specification','{"power":"83 kW at 10,500 rpm","engine":"Liquid-cooled DOHC inline four-cylinder","torque":"80 Nm at 9,000 rpm","weight":"212 kg wet (Suzuki archive reference)","model_year":"2017","transmission":"Six-speed constant-mesh","engine_capacity_cc":749}'::jsonb,2017,NULL,'Suzuki global archive specification','Suzuki Motor Corporation — Digital Library, 2017 GSX-S750','https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_041.php','manufacturer_primary_source_exact_model_checked_2026_11_12','2017 GSX-S750 archive specification, not GSX-S1000 or all markets/years.','Suzuki Motor Corporation — Digital Library, 2017 GSX-S750'),
(444,'market_launch','Honda CB500F — original European model announcement at EICMA 2012','{"power":"35 kW","design":"Naked middleweight roadster","engine_type":"Liquid-cooled parallel twin","announcement_date":"13 November 2012","european_model_year":"2013"}'::jsonb,2013,NULL,'Europe','Honda Global — 2013 line-up announcement, 13 November 2012','https://global.honda/en/newsroom/news/2012/2121113eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','European 2013 model announcement, not a statement about later CB500F editions.','Honda Global — 2013 line-up announcement, 13 November 2012'),
(445,'engineering','Honda CB500X — 2019 European 19-inch front wheel update','{"equipment":"Assist/slipper clutch, full LED lighting and updated LCD instruments","model_year":"2019","front_wheel":"19 inch","chassis_changes":"Longer suspension travel front and rear, slimmer seat, wider steering angle"}'::jsonb,2019,NULL,'Europe','Honda Global — 2019 middleweight line-up, 6 November 2018','https://global.honda/en/newsroom/news/2018/2181106eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','2019 CB500X revisions, not the 2013 original specification.','Honda Global — 2019 middleweight line-up, 6 November 2018'),
