(174,'chassis','Honda CBR600RR — 2013 Showa Big Piston Fork and bodywork update','{"wheels":"New 12-spoke wheels","updates":"MotoGP-inspired bodywork, refined rear suspension and revised injection/air intake","model_year":"2013","front_suspension":"41 mm Showa Big Piston Fork"}'::jsonb,2013,NULL,'Europe','Honda Global — 2013 line-up announcement, 13 November 2012','https://global.honda/en/newsroom/news/2012/2121113eng.html','manufacturer_primary_source_exact_model_checked_2026_11_12','Updates announced for 2013 CBR600RR, not fixed equipment for the whole CBR600RR history.','Honda Global — 2013 line-up announcement, 13 November 2012')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.end_year,d.market,d.source_name,d.source_url,'verified'
from documented d where exists(select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);

-- Keep audit idempotent separately so reruns can recover missing audits.
with documented(catalog_model_id,label,source_url,verification_basis,scope_note,source_version) as (values
